package com.friendinneed.smarthome;
import com.friendinneed.consent.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/smarthome") public class SmartHomeController { private final SmartHomeAdapter adapter;private final ConsentService consent;public SmartHomeController(SmartHomeAdapter a,ConsentService c){adapter=a;consent=c;} private void allowed(UUID id){if(!consent.isEnabled(id,IntegrationType.SMART_HOME))throw new org.springframework.security.access.AccessDeniedException("Smart home consent is required");}
 @GetMapping("/devices") List<DeviceState> devices(@RequestParam UUID profileId){allowed(profileId);return adapter.listDevices();}@GetMapping("/devices/{entityId}") DeviceState device(@RequestParam UUID profileId,@PathVariable String entityId){allowed(profileId);return adapter.getDevice(entityId);}@PostMapping("/devices/{entityId}/command") @ResponseStatus(HttpStatus.NO_CONTENT) void command(@RequestParam UUID profileId,@PathVariable String entityId,@RequestBody CommandRequest request){allowed(profileId);adapter.sendCommand(entityId,request.command(),request.params()==null?Map.of():request.params());} public record CommandRequest(String command,Map<String,Object> params){}
}
